1	// HMAC (RFC 2104) over any of the local hash functions.
2	
3	import { sha256, SHA256_BLOCK_SIZE } from './sha256.mjs';
4	import { sha384, sha512, SHA512_BLOCK_SIZE } from './sha512.mjs';
5	
6	/**
7	 * @param {(b: Uint8Array) => Uint8Array} hashFn
8	 * @param {number} blockSize
9	 * @param {Uint8Array|Array<number>} keyBytes
10	 * @param {Uint8Array|Array<number>} messageBytes
11	 * @returns {Uint8Array}
12	 */
13	export function hmac(hashFn, blockSize, keyBytes, messageBytes) {
14	  let key = keyBytes instanceof Uint8Array ? keyBytes : new Uint8Array(keyBytes || []);
15	  const msg =
16	    messageBytes instanceof Uint8Array ? messageBytes : new Uint8Array(messageBytes || []);
17	
18	  if (key.length > blockSize) key = hashFn(key);
19	
20	  const ipad = new Uint8Array(blockSize + msg.length);
21	  const opadKey = new Uint8Array(blockSize);
22	  for (let i = 0; i < blockSize; i++) {
23	    const k = i < key.length ? key[i] : 0;
24	    ipad[i] = k ^ 0x36;
25	    opadKey[i] = k ^ 0x5c;
26	  }
27	  ipad.set(msg, blockSize);
28	
29	  const inner = hashFn(ipad);
30	  const outer = new Uint8Array(blockSize + inner.length);
31	  outer.set(opadKey, 0);
32	  outer.set(inner, blockSize);
33	  return hashFn(outer);
34	}
