1	// Byte / UTF-8 helpers. Hand-rolled: no TextEncoder/TextDecoder.
2	
3	const REPLACEMENT = 0xfffd;
4	
5	/**
6	 * Encode a JS string to UTF-8 bytes.
7	 * Surrogate pairs are combined; lone surrogates become U+FFFD.
8	 * @param {string} str
9	 * @returns {Uint8Array}
10	 */
11	export function encodeUtf8(str) {
12	  const s = String(str);
13	  const out = [];
14	  for (let i = 0; i < s.length; i++) {
15	    let cp = s.charCodeAt(i);
16	    if (cp >= 0xd800 && cp <= 0xdbff) {
17	      // High surrogate: needs a following low surrogate.
18	      const next = i + 1 < s.length ? s.charCodeAt(i + 1) : -1;
19	      if (next >= 0xdc00 && next <= 0xdfff) {
20	        cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
21	        i++;
22	      } else {
23	        cp = REPLACEMENT;
24	      }
25	    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
26	      // Unpaired low surrogate.
27	      cp = REPLACEMENT;
28	    }
29	
30	    if (cp < 0x80) {
31	      out.push(cp);
32	    } else if (cp < 0x800) {
33	      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
34	    } else if (cp < 0x10000) {
35	      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
36	    } else {
37	      out.push(
38	        0xf0 | (cp >> 18),
39	        0x80 | ((cp >> 12) & 0x3f),
40	        0x80 | ((cp >> 6) & 0x3f),
41	        0x80 | (cp & 0x3f),
42	      );
43	    }
44	  }
45	  return new Uint8Array(out);
46	}
47	
48	function pushCodePoint(parts, cp) {
49	  if (cp < 0x10000) {
50	    parts.push(String.fromCharCode(cp));
51	  } else {
52	    const v = cp - 0x10000;
53	    parts.push(String.fromCharCode(0xd800 + (v >> 10), 0xdc00 + (v & 0x3ff)));
54	  }
55	}
56	
57	/**
58	 * Decode UTF-8 bytes to a JS string. Malformed input yields U+FFFD.
59	 * @param {Uint8Array|Array<number>} bytes
60	 * @returns {string}
61	 */
62	export function decodeUtf8(bytes) {
63	  const b = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
64	  const parts = [];
65	  let i = 0;
66	  while (i < b.length) {
67	    const b0 = b[i];
68	    let cp = -1;
69	    let need = 0;
70	    let min = 0;
71	
72	    if (b0 < 0x80) {
73	      cp = b0;
74	      need = 0;
75	      min = 0;
76	    } else if (b0 >= 0xc2 && b0 <= 0xdf) {
77	      cp = b0 & 0x1f;
78	      need = 1;
79	      min = 0x80;
80	    } else if (b0 >= 0xe0 && b0 <= 0xef) {
81	      cp = b0 & 0x0f;
82	      need = 2;
83	      min = 0x800;
84	    } else if (b0 >= 0xf0 && b0 <= 0xf4) {
85	      cp = b0 & 0x07;
86	      need = 3;
87	      min = 0x10000;
88	    } else {
89	      // 0x80-0xc1 (continuation or overlong lead) and 0xf5-0xff.
90	      parts.push(String.fromCharCode(REPLACEMENT));
91	      i++;
92	      continue;
93	    }
94	
95	    let ok = true;
96	    let j = 1;
97	    for (; j <= need; j++) {
98	      const bn = i + j < b.length ? b[i + j] : -1;
99	      if (bn < 0x80 || bn > 0xbf) {
100	        ok = false;
101	        break;
102	      }
103	      cp = (cp << 6) | (bn & 0x3f);
104	    }
105	
106	    if (!ok) {
107	      // Consume the lead plus however many valid continuations we saw.
108	      parts.push(String.fromCharCode(REPLACEMENT));
109	      i += j;
110	      continue;
111	    }
112	
113	    if (cp < min || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) {
114	      parts.push(String.fromCharCode(REPLACEMENT));
115	    } else {
116	      pushCodePoint(parts, cp);
117	    }
118	    i += need + 1;
119	  }
120	  return parts.join('');
121	}
122	
123	/**
124	 * Concatenate byte chunks.
125	 * @param {...(Uint8Array|Array<number>)} chunks
126	 * @returns {Uint8Array}
127	 */
128	export function concatBytes(...chunks) {
129	  let total = 0;
130	  for (let i = 0; i < chunks.length; i++) total += chunks[i].length;
131	  const out = new Uint8Array(total);
132	  let off = 0;
133	  for (let i = 0; i < chunks.length; i++) {
134	    const c = chunks[i];
135	    for (let j = 0; j < c.length; j++) out[off + j] = c[j] & 0xff;
136	    off += c.length;
137	  }
138	  return out;
139	}
140	
141	/**
142	 * Length-checked, constant-time-ish byte comparison.
143	 * @param {Uint8Array|Array<number>} a
144	 * @param {Uint8Array|Array<number>} b
145	 * @returns {boolean}
146	 */
147	export function bytesEqual(a, b) {
148	  if (!a || !b || a.length !== b.length) return false;
149	  let diff = 0;
150	  for (let i = 0; i < a.length; i++) diff |= (a[i] ^ b[i]) & 0xff;
151	  return diff === 0;
152	}
