// Base64url (RFC 4648 section 5) codec.
// Hand-rolled alphabet tables: no Buffer, no atob/btoa.

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

// Encode table: index (0..63) -> character.
const ENCODE_TABLE = new Array(64);
for (let i = 0; i < 64; i++) ENCODE_TABLE[i] = ALPHABET.charAt(i);

// Decode table: char code (0..127) -> 6-bit value, or -1 when not a base64 digit.
const DECODE_TABLE = new Int16Array(128).fill(-1);
for (let i = 0; i < 64; i++) DECODE_TABLE[ALPHABET.charCodeAt(i)] = i;
// Accept the standard (non url-safe) alphabet's two odd characters as aliases,
// mirroring Python's base64.urlsafe_b64decode, which happily decodes them.
DECODE_TABLE['+'.charCodeAt(0)] = 62;
DECODE_TABLE['/'.charCodeAt(0)] = 63;

/**
 * Encode bytes as base64url with the padding stripped.
 * @param {Uint8Array|Array<number>} bytes
 * @returns {string}
 */
export function base64UrlEncode(bytes) {
  const b = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes || []);
  const out = [];
  let i = 0;

  // Whole 3-byte groups -> 4 characters.
  for (; i + 2 < b.length; i += 3) {
    const n = ((b[i] & 0xff) << 16) | ((b[i + 1] & 0xff) << 8) | (b[i + 2] & 0xff);
    out.push(
      ENCODE_TABLE[(n >>> 18) & 0x3f],
      ENCODE_TABLE[(n >>> 12) & 0x3f],
      ENCODE_TABLE[(n >>> 6) & 0x3f],
      ENCODE_TABLE[n & 0x3f],
    );
  }

  // Tail: 1 byte -> 2 characters, 2 bytes -> 3 characters (padding stripped).
  const rem = b.length - i;
  if (rem === 1) {
    const n = (b[i] & 0xff) << 16;
    out.push(ENCODE_TABLE[(n >>> 18) & 0x3f], ENCODE_TABLE[(n >>> 12) & 0x3f]);
  } else if (rem === 2) {
    const n = ((b[i] & 0xff) << 16) | ((b[i + 1] & 0xff) << 8);
    out.push(
      ENCODE_TABLE[(n >>> 18) & 0x3f],
      ENCODE_TABLE[(n >>> 12) & 0x3f],
      ENCODE_TABLE[(n >>> 6) & 0x3f],
    );
  }

  return out.join('');
}

/**
 * Decode a base64url string. Missing padding is tolerated; `-`/`_` (and their
 * standard-alphabet counterparts `+`/`/`) are accepted.
 * @param {string} str
 * @returns {Uint8Array}
 * @throws {Error} on an invalid character or an impossible length
 */
export function base64UrlDecode(str) {
  if (typeof str !== 'string') {
    if (str instanceof Uint8Array || Array.isArray(str)) {
      let s = '';
      for (let i = 0; i < str.length; i++) s += String.fromCharCode(str[i] & 0xff);
      return base64UrlDecode(s);
    }
    throw new Error('Invalid base64url input: expected a string');
  }

  // Trailing padding is optional and is re-derived from the length below.
  let end = str.length;
  while (end > 0 && str.charAt(end - 1) === '=') end--;
  const body = str.slice(0, end);

  const rem = body.length % 4;
  if (rem === 1) {
    throw new Error('Invalid base64url string: incorrect length');
  }

  const outLen = ((body.length - rem) / 4) * 3 + (rem === 2 ? 1 : rem === 3 ? 2 : 0);
  const out = new Uint8Array(outLen);

  let o = 0;
  let acc = 0;
  let accBits = 0;
  for (let i = 0; i < body.length; i++) {
    const code = body.charCodeAt(i);
    const v = code < 128 ? DECODE_TABLE[code] : -1;
    if (v < 0) {
      throw new Error('Invalid base64url character: ' + JSON.stringify(body.charAt(i)));
    }
    acc = (acc << 6) | v;
    accBits += 6;
    if (accBits >= 8) {
      accBits -= 8;
      out[o++] = (acc >>> accBits) & 0xff;
    }
  }

  return out;
}

// Exception hierarchy mirroring python-jose's `jose.exceptions`.
// `.name` is set to the class name so an uncaught throw prints a line that
// reads like Python's `JWSSignatureError: ...`.

export class JOSEError extends Error {
  constructor(message) {
    super(message === undefined || message === null ? '' : String(message));
    this.name = 'JOSEError';
  }
}

export class JWSError extends JOSEError {
  constructor(message) {
    super(message);
    this.name = 'JWSError';
  }
}

export class JWSSignatureError extends JWSError {
  constructor(message) {
    super(message);
    this.name = 'JWSSignatureError';
  }
}

export class JWSAlgorithmError extends JWSError {
  constructor(message) {
    super(message);
    this.name = 'JWSAlgorithmError';
  }
}

export class JWTError extends JOSEError {
  constructor(message) {
    super(message);
    this.name = 'JWTError';
  }
}

export class JWTClaimsError extends JWTError {
  constructor(message) {
    super(message);
    this.name = 'JWTClaimsError';
  }
}

export class ExpiredSignatureError extends JWTError {
  constructor(message) {
    super(message);
    this.name = 'ExpiredSignatureError';
  }
}

// Algorithm registry for the HMAC family of JWS algorithms.
// Hashing/HMAC primitives come from the sibling local modules only.

import { sha256, SHA256_BLOCK_SIZE } from '../hash/sha256.mjs';
import { sha384, sha512, SHA512_BLOCK_SIZE } from '../hash/sha512.mjs';
import { hmacSha256, hmacSha384, hmacSha512 } from '../hash/hmac.mjs';

const HS256 = 'HS256';
const HS384 = 'HS384';
const HS512 = 'HS512';

// Internal map: alg name -> primitives used to sign/verify with it.
const ALGORITHM_SPECS = new Map([
  [HS256, { name: HS256, hashFn: sha256, blockSize: SHA256_BLOCK_SIZE, hmac: hmacSha256 }],
  [HS384, { name: HS384, hashFn: sha384, blockSize: SHA512_BLOCK_SIZE, hmac: hmacSha384 }],
  [HS512, { name: HS512, hashFn: sha512, blockSize: SHA512_BLOCK_SIZE, hmac: hmacSha512 }],
]);

const SUPPORTED = new Set([HS256, HS384, HS512]);

// alg -> hash function, used for the `at_hash` claim.
const HASHES = new Map([
  [HS256, sha256],
  [HS384, sha384],
  [HS512, sha512],
]);

export const ALGORITHMS = Object.freeze({
  HS256,
  HS384,
  HS512,
  NONE: 'none',
  HMAC: new Set([HS256, HS384, HS512]),
  SUPPORTED,
  ALL: new Set([HS256, HS384, HS512]),
  HASHES,
});

/**
 * @param {string} alg
 * @returns {boolean}
 */
export function isSupported(alg) {
  return typeof alg === 'string' && SUPPORTED.has(alg);
}

/**
 * Look up the primitives for an algorithm name.
 * @param {string} alg
 * @returns {{name: string, hashFn: Function, blockSize: number, hmac: Function}|null}
 */
export function getAlgorithmSpec(alg) {
  if (typeof alg !== 'string') return null;
  return ALGORITHM_SPECS.get(alg) || null;
}

