// JWS (JSON Web Signature) compact serialization, HMAC family only.
// Mirrors python-jose's `jose.jws` interface.

import { encodeUtf8, decodeUtf8, bytesEqual } from '../codec/bytes.mjs';
import { base64UrlEncode, base64UrlDecode } from '../codec/base64url.mjs';
import { pyJsonDumps, pyJsonLoads } from '../py/pyjson.mjs';
import { ALGORITHMS, getAlgorithmSpec } from './constants.mjs';
import { JWSError, JWSSignatureError, JWSAlgorithmError } from './errors.mjs';

/**
 * Iterate `[key, value]` pairs of a Map or a plain object.
 * @param {Map<*,*>|Object} obj
 * @returns {Array<[*, *]>}
 */
function entriesOf(obj) {
  if (obj instanceof Map) return [...obj.entries()];
  if (Array.isArray(obj)) return obj.map((pair) => [pair[0], pair[1]]);
  return Object.keys(obj).map((k) => [k, obj[k]]);
}

/**
 * Coerce a key to raw bytes. Strings are UTF-8 encoded (python-jose's
 * HMACKey does the same); an `oct` JWK (Map/object with `k`) is base64url
 * decoded.
 * @param {string|Uint8Array|Array<number>|Map<*,*>|Object} key
 * @returns {Uint8Array}
 */
function toKeyBytes(key) {
  if (key instanceof Uint8Array) return key;
  if (typeof key === 'string') return encodeUtf8(key);
  if (Array.isArray(key)) return new Uint8Array(key);
  if (key instanceof Map) {
    if (key.has('k')) return base64UrlDecode(String(key.get('k')));
    throw new JWSError('Invalid JWK: missing "k" parameter');
  }
  if (key && typeof key === 'object') {
    if ('k' in key) return base64UrlDecode(String(key.k));
    throw new JWSError('Invalid JWK: missing "k" parameter');
  }
  if (key === null || key === undefined) return new Uint8Array(0);
  throw new JWSError('Unable to interpret key as an HMAC secret');
}

/**
 * `{"typ":"JWT","alg":<algorithm>}` merged with `additionalHeaders`, JSON
 * serialized with sorted keys and no whitespace, then base64url encoded.
 * @param {string} algorithm
 * @param {Map<*,*>|Object|null} additionalHeaders
 * @returns {string}
 */
function encodeHeader(algorithm, additionalHeaders) {
  const header = new Map([
    ['typ', 'JWT'],
    ['alg', algorithm],
  ]);
  if (additionalHeaders) {
    for (const [k, v] of entriesOf(additionalHeaders)) header.set(k, v);
  }
  const json = pyJsonDumps(header, {
    ensureAscii: true,
    separators: [',', ':'],
    sortKeys: true,
  });
  return base64UrlEncode(encodeUtf8(json));
}

/**
 * @param {Uint8Array|string|Map<*,*>|Object|Array<*>} payload
 * @returns {string} base64url encoded payload
 */
function encodePayload(payload) {
  if (payload instanceof Uint8Array) return base64UrlEncode(payload);
  if (typeof payload === 'string') return base64UrlEncode(encodeUtf8(payload));
  if (payload instanceof Map || Array.isArray(payload) || (payload && typeof payload === 'object')) {
    const json = pyJsonDumps(payload, {
      ensureAscii: true,
      separators: [',', ':'],
      sortKeys: false,
    });
    return base64UrlEncode(encodeUtf8(json));
  }
  throw new JWSError('Unable to encode payload: unsupported type');
}

/**
 * Sign a payload, producing a compact JWS.
 *
 * @param {Uint8Array|string|Map<*,*>|Object} payload
 * @param {string|Uint8Array|Map<*,*>|Object} key
 * @param {{headers?: Map<*,*>|Object|null, algorithm?: string}} [opts]
 * @returns {string} `<header>.<payload>.<signature>`
 */
export function sign(payload, key, { headers = null, algorithm = ALGORITHMS.HS256 } = {}) {
  const spec = getAlgorithmSpec(algorithm);
  if (!spec || !ALGORITHMS.SUPPORTED.has(algorithm)) {
    throw new JWSAlgorithmError('Algorithm ' + algorithm + ' not supported.');
  }
  const encodedHeader = encodeHeader(algorithm, headers);
  const encodedPayload = encodePayload(payload);
  const signingInput = encodedHeader + '.' + encodedPayload;
  const signature = spec.hmac(toKeyBytes(key), encodeUtf8(signingInput));
  return signingInput + '.' + base64UrlEncode(signature);
}

/**
 * Split and decode a compact JWS without verifying it.
 * @param {string|Uint8Array} token
 * @returns {{header: Map<*,*>, payload: Uint8Array, signingInput: string, signature: Uint8Array}}
 */
function load(token) {
  const text = typeof token === 'string' ? token : decodeUtf8(token);
  const parts = text.split('.');
  if (parts.length < 3) {
    throw new JWSError('Not enough segments');
  }
  const headerSegment = parts[0];
  // Extra dots stay inside the claims segment (python-jose rsplits on the last
  // dot first), which then fails to decode -- same behavior, same error.
  const claimsSegment = parts.slice(1, parts.length - 1).join('.');
  const cryptoSegment = parts[parts.length - 1];
  const signingInput = headerSegment + '.' + claimsSegment;

  let headerData;
  try {
    headerData = base64UrlDecode(headerSegment);
  } catch (e) {
    throw new JWSError('Invalid header padding');
  }

  let header;
  try {
    header = pyJsonLoads(decodeUtf8(headerData));
  } catch (e) {
    throw new JWSError('Invalid header string: ' + (e && e.message ? e.message : String(e)));
  }
  if (!(header instanceof Map)) {
    throw new JWSError('Invalid header string: must be a json object');
  }

  let payload;
  try {
    payload = base64UrlDecode(claimsSegment);
  } catch (e) {
    throw new JWSError('Invalid payload padding');
  }

  let signature;
  try {
    signature = base64UrlDecode(cryptoSegment);
  } catch (e) {
    throw new JWSError('Invalid crypto padding');
  }

  return { header, payload, signingInput, signature };
}

/**
 * @param {string} signingInput
 * @param {Map<*,*>} header
 * @param {Uint8Array} signature
 * @param {*} key
 * @param {Array<string>|Set<string>|string|null} algorithms
 */
function verifySignature(signingInput, header, signature, key, algorithms) {
  const alg = header.get('alg');
  if (!alg) {
    throw new JWSAlgorithmError('No algorithm was specified in the JWS header.');
  }
  if (algorithms !== null && algorithms !== undefined) {
    const allowed = typeof algorithms === 'string' ? [algorithms] : Array.from(algorithms);
    if (!allowed.includes(alg)) {
      throw new JWSAlgorithmError('The specified alg value is not allowed');
    }
  }
  const spec = getAlgorithmSpec(alg);
  if (!spec) {
    throw new JWSAlgorithmError('Invalid or unsupported algorithm: ' + alg);
  }
  const expected = spec.hmac(toKeyBytes(key), encodeUtf8(signingInput));
  // Constant-time comparison (length-checked) from the codec module.
  if (!bytesEqual(expected, signature)) {
    throw new JWSSignatureError('Signature verification failed.');
  }
}

/**
 * Verify a compact JWS and return its raw payload bytes.
 *
 * @param {string|Uint8Array} token
 * @param {string|Uint8Array|Map<*,*>|Object} key
 * @param {Array<string>|Set<string>|string|null} [algorithms]
 * @param {boolean} [verifyFlag] when false the signature is not checked
 * @returns {Uint8Array}
 */
export function verify(token, key, algorithms = null, verifyFlag = true) {
  const loaded = load(token);
  if (verifyFlag) {
    verifySignature(loaded.signingInput, loaded.header, loaded.signature, key, algorithms);
  }
  return loaded.payload;
}

/**
 * Header of a token, without verifying the signature.
 * @param {string|Uint8Array} token
 * @returns {Map<*,*>}
 */
export function getUnverifiedHeader(token) {
  return load(token).header;
}

/** Alias matching python-jose's `get_unverified_headers`. */
export function getUnverifiedHeaders(token) {
  return getUnverifiedHeader(token);
}

/**
 * Raw payload bytes of a token, without verifying the signature.
 * @param {string|Uint8Array} token
 * @returns {Uint8Array}
 */
export function getUnverifiedClaims(token) {
  return load(token).payload;
}

// JWT (JSON Web Token) encode/decode, mirroring python-jose's `jose.jwt`.

import { encodeUtf8, decodeUtf8 } from '../codec/bytes.mjs';
import { base64UrlEncode } from '../codec/base64url.mjs';
import { pyJsonDumps, pyJsonLoads } from '../py/pyjson.mjs';
import { ALGORITHMS } from './constants.mjs';
import * as jws from './jws.mjs';
import { JWTError, JWTClaimsError, ExpiredSignatureError } from './errors.mjs';

/** Option defaults, matching python-jose. */
const DEFAULT_OPTIONS = {
  verify_signature: true,
  verify_aud: true,
  verify_iat: true,
  verify_exp: true,
  verify_nbf: true,
  verify_iss: true,
  verify_sub: true,
  verify_jti: true,
  verify_at_hash: true,
  require_aud: false,
  require_iat: false,
  require_exp: false,
  require_nbf: false,
  require_iss: false,
  require_sub: false,
  require_jti: false,
  require_at_hash: false,
  leeway: 0,
};

/**
 * @param {Map<*,*>|Object} obj
 * @returns {Array<[*, *]>}
 */
function entriesOf(obj) {
  if (obj instanceof Map) return [...obj.entries()];
  return Object.keys(obj).map((k) => [k, obj[k]]);
}

/**
 * Copy claims into a Map, preserving insertion order.
 * @param {Map<*,*>|Object} claims
 * @returns {Map<*,*>}
 */
function toClaimsMap(claims) {
  if (claims instanceof Map) return new Map(claims);
  if (claims && typeof claims === 'object' && !Array.isArray(claims)) {
    return new Map(entriesOf(claims));
  }
  throw new JWTError('Claims must be a dict (Map) or a plain object');
}

/** Current time as Unix epoch seconds (UTC), like Python's timegm(utcnow()). */
function nowEpochSeconds() {
  return Math.floor(Date.now() / 1000);
}

/**
 * Python's `int(x)` for the values our data model can hold.
 * Returns null when Python would have raised (i.e. the claim is not numeric).
 * @param {*} value
 * @returns {bigint|null}
 */
function asInt(value) {
  if (typeof value === 'bigint') return value;
  if (typeof value === 'boolean') return value ? 1n : 0n;
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) return null;
    return BigInt(Math.trunc(value));
  }
  if (typeof value === 'string') {
    const t = value.trim();
    if (/^[+-]?\d+$/.test(t)) return BigInt(t);
    return null;
  }
  return null;
}

/**
 * Left half of the digest of `accessToken`, base64url encoded (OIDC at_hash).
 * @param {string} accessToken
 * @param {string} algorithm
 * @returns {string}
 */
export function calculateAtHash(accessToken, algorithm) {
  const hashFn = ALGORITHMS.HASHES.get(algorithm);
  if (!hashFn) {
    throw new JWTClaimsError('Unable to calculate at_hash to verify against token claims.');
  }
  const digest = hashFn(encodeUtf8(String(accessToken)));
  const cutAt = Math.floor(digest.length / 2);
  return base64UrlEncode(digest.subarray(0, cutAt));
}

// ---------------------------------------------------------------------------
// encode
// ---------------------------------------------------------------------------

/**
 * Encode claims into a signed compact JWT.
 *
 * The claims are serialized with insertion order preserved (NOT sorted) --
 * only the header is sorted.
 *
 * @param {Map<*,*>|Object} claims dict-like; ints should be BigInt
 * @param {string|Uint8Array|Map<*,*>|Object} key
 * @param {string} [algorithm]
 * @param {Map<*,*>|Object|null} [headers] extra header parameters
 * @param {string|null} [accessToken] when set, an `at_hash` claim is added
 * @returns {string}
 */
export function encode(
  claims,
  key,
  algorithm = ALGORITHMS.HS256,
  headers = null,
  accessToken = null,
) {
  const working = toClaimsMap(claims);

  // Known time claims given as Date objects become epoch-second ints.
  for (const timeClaim of ['exp', 'iat', 'nbf']) {
    const value = working.get(timeClaim);
    if (value instanceof Date) {
      working.set(timeClaim, BigInt(Math.floor(value.getTime() / 1000)));
    }
  }

  if (accessToken) {
    working.set('at_hash', calculateAtHash(accessToken, algorithm));
  }

  const payload = pyJsonDumps(working, {
    ensureAscii: true,
    separators: [',', ':'],
    sortKeys: false,
  });

  return jws.sign(payload, key, { headers, algorithm });
}

// ---------------------------------------------------------------------------
// decode
// ---------------------------------------------------------------------------

/**
 * Verify and decode a compact JWT.
 *
 * @param {string|Uint8Array} token
 * @param {string|Uint8Array|Map<*,*>|Object} key
 * @param {{algorithms?: Array<string>|Set<string>|string|null,
 *          options?: Map<*,*>|Object|null,
 *          audience?: string|null, issuer?: string|Array<string>|null,
 *          subject?: string|null, accessToken?: string|null}} [opts]
 * @returns {Map<*,*>} the claims, key order preserved
 */
export function decode(
  token,
  key,
  { algorithms = null, options = null, audience = null, issuer = null, subject = null, accessToken = null } = {},
) {
  const merged = { ...DEFAULT_OPTIONS };
  if (options) {
    for (const [k, v] of entriesOf(options)) merged[String(k)] = v;
  }

  const verifySignature = merged.verify_signature === undefined ? true : !!merged.verify_signature;

  // Signature/segment problems propagate as the original JWS error classes
  // (JWSSignatureError, JWSAlgorithmError, JWSError), which all derive from
  // JOSEError, so the class name printed for an uncaught throw is precise.
  const payload = jws.verify(token, key, algorithms, verifySignature);

  // The header's alg is needed to verify `at_hash`.
  const algorithm = jws.getUnverifiedHeader(token).get('alg');

  let claims;
  try {
    claims = pyJsonLoads(decodeUtf8(payload));
  } catch (e) {
    throw new JWTError('Invalid payload string: ' + (e && e.message ? e.message : String(e)));
  }
  if (!(claims instanceof Map)) {
    throw new JWTError('Invalid payload string: must be a json object');
  }

  validateClaims(claims, {
    audience,
    issuer,
    subject,
    algorithm,
    accessToken,
    options: merged,
  });

  return claims;
}

/**
 * Run every enabled claim check, in python-jose's order.
 * @param {Map<*,*>} claims
 * @param {{audience?: *, issuer?: *, subject?: *, algorithm?: *, accessToken?: *, options: Object}} ctx
 */
export function validateClaims(claims, ctx = { options: {} }) {
  const options = { ...DEFAULT_OPTIONS, ...(ctx.options || {}) };
  const leeway = Number(options.leeway || 0);

  // require_* first: a missing required claim is fatal, and a present one
  // forces its verify_* counterpart on.
  for (const optionName of Object.keys(options)) {
    if (!optionName.startsWith('require_') || !options[optionName]) continue;
    const claimName = optionName.slice('require_'.length);
    if (!claims.has(claimName)) {
      throw new JWTClaimsError('missing ' + claimName + ' claim');
    }
    options['verify_' + claimName] = true;
  }

  const audience = ctx.audience === undefined ? null : ctx.audience;
  if (!(audience === null || typeof audience === 'string')) {
    throw new JWTError('audience must be a string or None');
  }

  if (options.verify_iat) validateIat(claims);
  if (options.verify_nbf) validateNbf(claims, leeway);
  if (options.verify_exp) validateExp(claims, leeway);
  if (options.verify_aud) validateAud(claims, audience);
  if (options.verify_iss) validateIss(claims, ctx.issuer === undefined ? null : ctx.issuer);
  if (options.verify_sub) validateSub(claims, ctx.subject === undefined ? null : ctx.subject);
  if (options.verify_jti) validateJti(claims);
  if (options.verify_at_hash) validateAtHash(claims, ctx.accessToken, ctx.algorithm);
