function validateNbf(claims, leeway) {
  if (!claims.has('nbf')) return;
  const nbf = asInt(claims.get('nbf'));
  if (nbf === null) {
    throw new JWTClaimsError('Not Before claim (nbf) must be an integer.');
  }
  const now = nowEpochSeconds();
  if (Number(nbf) > now + leeway) {
    throw new JWTClaimsError('The token is not yet valid (nbf)');
  }
}

function validateExp(claims, leeway) {
  if (!claims.has('exp')) return;
  const exp = asInt(claims.get('exp'));
  if (exp === null) {
    throw new JWTClaimsError('Expiration Time claim (exp) must be an integer.');
  }
  const now = nowEpochSeconds();
  if (Number(exp) < now - leeway) {
    throw new ExpiredSignatureError('Signature has expired.');
  }
