function validateAud(claims, audience) {
  // No `aud` claim at all: nothing to check, silently accept.
  if (!claims.has('aud')) return;

  let audienceClaims = claims.get('aud');
  if (typeof audienceClaims === 'string') audienceClaims = [audienceClaims];
  if (!Array.isArray(audienceClaims)) {
    throw new JWTClaimsError('Invalid claim format in token');
  }
  for (const entry of audienceClaims) {
    if (typeof entry !== 'string') {
      throw new JWTClaimsError('Invalid claim format in token');
    }
  }
  if (!audienceClaims.includes(audience)) {
    throw new JWTClaimsError('Invalid audience');
  }
}

function validateIss(claims, issuer) {
  if (issuer === null || issuer === undefined) return;
  const allowed = typeof issuer === 'string' ? [issuer] : Array.from(issuer);
  const value = claims.has('iss') ? claims.get('iss') : undefined;
  if (!allowed.includes(value)) {
    throw new JWTClaimsError('Invalid issuer');
  }
