// CPython `print()` reproduced in pure JavaScript.

import { pyStr } from './pyrepr.mjs';

/**
 * CPython `print(*values)`: joins str(v) with a single space and writes the
 * result plus a trailing newline to stdout, byte-for-byte like Python.
 *
 * @param {...*} values
 * @returns {void}
 */
export function pyPrint(...values) {
  let out = '';
  for (let i = 0; i < values.length; i++) {
    if (i > 0) out += ' ';
    out += pyStr(values[i]);
  }
  process.stdout.write(out + '\n');
}
